const locale=document.getElementById('page-language');locale.addEventListener('change',()=>{location.href=locale.value+location.hash});
const menu=document.querySelector('.menu-toggle'),nav=document.getElementById('navigation');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open)});document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('is-open');menu.setAttribute('aria-expanded','false')}});
const checks=[...document.querySelectorAll('[data-check]')];
if(checks.length){const key='bkmun-october-2026-preparation-v1';let saved=[];try{const stored=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(stored))saved=stored.filter(x=>Number.isInteger(x)&&x>=0&&x<checks.length)}catch{document.getElementById('storage-note').textContent=document.body.dataset.storageWarning}
function update(){const count=checks.filter(c=>c.checked).length;document.getElementById('check-progress').textContent=count+' / '+checks.length+' '+document.body.dataset.progressLabel;document.getElementById('check-bar').value=count}
for(const check of checks){check.checked=saved.includes(Number(check.dataset.check));check.addEventListener('change',()=>{update();try{localStorage.setItem(key,JSON.stringify(checks.filter(c=>c.checked).map(c=>Number(c.dataset.check))))}catch{document.getElementById('storage-note').textContent=document.body.dataset.storageWarning}})}update();}
